/// <summary>
/// Updates multiple <c>WMSOrderTrans</c> records.
/// </summary>
/// <param name="_packedMap">
/// A packed map.
/// </param>
/// <param name="_wmsPickPalletId">
/// A <c>WMSPickPalletID</c> value; optional.
/// </param>
/// <param name="_worker">
/// The worker that performs the operation; optional.
/// </param>
/// <param name="_time">
/// The duration of the operation; optional.
/// </param>
/// <remarks>
/// An <c>OrderId</c> value is required for performance reasons so an index can be used.
/// </remarks>
/// <exception cref="M:exception::UpdateConflict">
/// An update conflict occurred.
/// </exception>
/// <exception cref="M:exception::UpdateConflictNotRecovered">
/// An update conflict cannot be recovered.
/// </exception>
/// <exception cref="M:exception::error">
/// The <c>RecVersion</c> passed as argument differs from the <c>RecVersion</c> of the selected record
/// </exception>
static public void finishPickingLinesMulti(
    container           _packedMap,
    WMSPickPalletId     _wmsPickPalletId,
    HcmWorkerRecId      _worker,
    WMSExpeditionTime   _time)
{
    next finishPickingLinesMulti(_packedMap, _wmsPickPalletId, _worker, _time);

    WMSOrderTransType::METCustomerMDFCalculation(_packedMap);
}

/// <summary>
/// Calculate Customer MDF for all WMSPickingRouteId in the packed list
/// </summary>
/// <param name = "_metPackedList">container</param>
public static void METCustomerMDFCalculation(container _packedMap)
{
    METCustomerMDFCalculation_WMSOrderTrans custMDFCalculation = new METCustomerMDFCalculation_WMSOrderTrans();
    custMDFCalculation.parmWMSOrderTransMulti(_packedMap);
    custMDFCalculation.process();
}
